def weights(axis):
    return np.r_[np.diff(axis)[0] / 2, (axis[2:] - axis[:-2]) / 2, np.diff(axis)[-1] / 2]


def density_and_levels(mass, q, k):
    assert mass.shape == (len(q), len(k)) and np.isclose(mass.sum(), 1, atol=1e-10)
    density = mass / (weights(q)[:, None] * weights(k)[None, :])
    order = np.argsort(density.ravel())[::-1]
    cumulative = np.cumsum(mass.ravel()[order])
    levels = [density.ravel()[order[min(np.searchsorted(cumulative, p), len(order) - 1)]]
              for p in (.95, .68)]
    return density, levels


def contour(ax, mass, q, k, role, *, zorder=2):
    density, levels = density_and_levels(mass, q, k)
    ax.contour(q, k, density.T, levels=levels, colors=[role['color']],
               linewidths=[1.35, 2.8], linestyles=[role['linestyle']], zorder=zorder)

